EngineUtil = {}

local function sendEnterOtherGame(rakssid, gameType, targetId, mapId)
    local player = PlayerManager:getPlayerByRakssid(rakssid)
    if not player then
        return
    end
    if not player.isKickOut then
        DBManager:callSavePlayerData(player)
    end
    if DBManager:hasDataSaving(player.userId) then
        LuaTimer:schedule(function()
            sendEnterOtherGame(rakssid, gameType, targetId, mapId)
        end, 500)
        return
    end
    HostApi.sendEnterOtherGame(rakssid, gameType, targetId, mapId)
end

function EngineUtil.sendEnterOtherGame(rakssid, gameType, targetId, mapId)
    local player = PlayerManager:getPlayerByRakssid(rakssid)
    if not player then
        return
    end
    mapId = mapId or ""
    sendEnterOtherGame(rakssid, gameType, targetId, mapId)
end

function EngineUtil.disposePlatformOrder(userId, orderId, isConsume)
    if isConsume then
        OrderManager.addGameBilling(userId, orderId)
        WebService:ResumeOrder(orderId)
    else
        WebService:CancelOrder(userId, orderId)
    end
end

function EngineUtil.disposeGameCashOrder(userId, orderId, isConsume)
    if isConsume then
        OrderManager.addGameCashBillings(userId, orderId)
        WebService:ReceivedRechargeOrder(userId, orderId)
    else
        WebService:CancelRechargeOrder(userId, orderId)
    end
end

return EngineUtil